{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Codeine, the closest retrieved morphinan analogue sharing the 3-methoxy and N-methyl morphinan core, has absolute oral bioavailability of 42–71% in healthy volunteers, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Codeine sulfate in healthy subjects showed an oral bioavailability of 80.5%, reinforcing high oral absorption for the 3-methoxy morphinan scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Ethylmorphine, another 3-alkoxy morphinan, had a minimum oral availability of 0.74 (median) in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Samidorphan, a morphinan-based opioid modulator, showed absolute oral bioavailability of 69% in healthy volunteers, supporting high F for the morphinan scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Diacetylmorphine, a morphinan prodrug, reached 64.5% oral bioavailability at a high dose, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Morphine, a close but less similar analogue lacking the 3-methoxy group, had absolute oral bioavailability of 32%, still above the 20% threshold and supportive of high F, though with lower transferability due to free-phenol conjugation liabilities.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Noscapine, a structurally distinct isoquinoline alkaloid, had absolute oral bioavailability of 30%, supportive of F ≥ 20% but with lower transferability to the morphinan query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Ketobemidone, a phenylpiperidine opioid, had mean oral bioavailability of 34%, supportive of F ≥ 20% but with limited structural transferability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is oxycodone, a 3-methoxy-6-keto N-methyl morphinan. The closest analogues (codeine, codeine sulfate, ethylmorphine) have oral bioavailability values mostly 40–80%, and other morphinans/opioids also meet or exceed 20%. The 3-methoxy group reduces first-pass conjugation relative to morphine, supporting high F. Therefore F ≥ 20% is strongly supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for oxycodone itself was retrieved; direct human F data for oxycodone would remove residual uncertainty.",
    "The retrieved set lacks a close analogue with the 6-keto and 14-hydroxy substitution pattern of oxycodone; codeine and ethylmorphine have 6-hydroxy instead.",
    "Morphine-6-glucuronide is reported qualitatively as having poor oral bioavailability, but no numeric F value is given, so its threshold relevance is uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

